param([string]$GameRoot='F:/SteamLibrary/steamapps/common/RimWorld',[switch]$Check)
# Read-only bounded replay of existing matched derived sources and Core XML.
$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$base=Join-Path $root 'docs/research/rimworld/evidence'
$dllHash='eff7d97949f919fb2b151ebfb906e9be749b63410b7dbda78eeebb7972b245c3'
$engineHash='587a18e18e13acfc7fd8783a44c24c7da0781dadf6b9fb9dd5e2e38a9cdfae78'
function Digest([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
function TextDigest([string]$s){[Convert]::ToHexString([Security.Cryptography.SHA256]::HashData([Text.Encoding]::UTF8.GetBytes($s))).ToLowerInvariant()}
function LF([string]$s){$s.Replace(([string][char]13+[char]10),[string][char]10)}
if((Digest (Join-Path $GameRoot 'Assembly-CSharp.dll')) -ne $dllHash){throw 'Game assembly changed'}
if((Digest (Join-Path $root '../../tools/ilspy/lib/netstandard2.0/ICSharpCode.Decompiler.dll')) -ne $engineHash){throw 'Decompiler changed'}
$groups=[Collections.Generic.HashSet[string]]::new()
function Source([string]$group,[string]$type,[int]$start,[int]$end){
 $m=Get-Content (Join-Path $base "$group-manifest.json") -Raw|ConvertFrom-Json
 if($m.source_sha256 -ne $dllHash -or $m.engine_sha256 -ne $engineHash){throw "Mismatched provenance: $group"}
 $entries=@($m.types|Where-Object type -eq $type)
 if($entries.Count -ne 1){throw "Unknown type: $group/$type"}
 $t=$entries[0];$file=Join-Path $root $t.local_file
 if((Digest $file) -ne $t.sha256){throw "Changed source: $file"}
 $lines=[IO.File]::ReadAllText($file).Split([char]10)
 if($lines.Length -ne $t.lines -or $start -lt 1 -or $end -lt $start -or $end -gt $t.lines){throw "Invalid source range: $group/$type"}
 [void]$groups.Add($group)
 [ordered]@{group=$group;type=$type;file=$t.local_file;sha256=$t.sha256;lines=@($start,$end);excerpt_sha256=(TextDigest ($lines[($start-1)..($end-1)] -join [char]10))}
}
$xmlRelative='Data/Core/Defs/Misc/BillDefs/BillStoreModeDefs.xml'
$xmlFile=Join-Path $GameRoot $xmlRelative;[xml]$xml=[IO.File]::ReadAllText($xmlFile)
$modes=@(foreach($n in $xml.SelectNodes('/Defs/BillStoreModeDef')){[ordered]@{defName=$n.defName;label=$n.label;listOrder=[int]$n.listOrder;node_sha256=TextDigest $n.OuterXml}})
if(($modes.defName -join ';') -cne 'DropOnFloor;BestStockpile;SpecificStockpile' -or ($modes.listOrder -join ';') -ne '0;10;20'){throw 'Core output-mode definitions changed'}
$claims=@(
 [ordered]@{id='OUT01';finding='Bill_Production defaults to BestStockpile. storeMode/storeGroup govern output; includeGroup governs counting through separate fields, accessors and setters. They do not imply an ingredient source or named-worker change.';sources=@((Source 'stonecutting' 'RimWorld.Bill_Production' 12 38),(Source 'stonecutting' 'RimWorld.Bill_Production' 177 205),(Source 'stonecutting' 'Verse.RecipeWorkerCounter' 20 100))},
 [ordered]@{id='OUT02';finding='FinishRecipeAndStartStoringProduct calculates ingredients, generates products, consumes ingredients, calls Notify_IterationCompleted and records completion BEFORE output selection. RepeatCount decrements here. Later shipment failure does not roll back the completed iteration or recreate ingredients/UFT.';sources=@((Source 'food' 'Verse.AI.Toils_Recipe' 180 200),(Source 'food' 'Verse.AI.Toils_Recipe' 346 376),(Source 'stonecutting' 'RimWorld.Bill_Production' 245 259),(Source 'production-bills' 'RimWorld.Bill_ProductionWithUft' 95 115))},
 [ordered]@{id='OUT03';finding='DropOnFloor attempts Near placement of EVERY generated product at the actor position and ends the job Succeeded. Zero products also ends Succeeded. Placement failures are logged; this is not a guarantee that arbitrary blocked maps accept every product.';sources=@((Source 'food' 'Verse.AI.Toils_Recipe' 201 235))},
 [ordered]@{id='OUT04';finding='For Best/Specific only products[0] is considered for maker delivery; products[1..] are placed Near the maker. Ordinary recipe product definitions are yielded in list order; special product routines can yield multiple Things. A Thing stackCount may exceed a normal stack limit until subsequent carry/placement splitting. First product is not the most valuable or nearest product.';sources=@((Source 'food' 'Verse.AI.Toils_Recipe' 239 261),(Source 'food' 'Verse.GenRecipe' 8 72))},
 [ordered]@{id='OUT05';finding='After a cell is found, MaxStackSpaceEver is min(def.stackLimit, rounded CarryingCapacity/VolumePerUnit). Excess from products[0] is split off and attempted Near the maker; capacity0 ends Succeeded. Otherwise TryStartCarry then direct HaulToCellStorageJob and StartJob keepCarryingThingOverride=true. This path does not consult ordinary Haul priority; dead/downed and capacity constraints still exist.';sources=@((Source 'food' 'Verse.AI.Toils_Recipe' 262 284),(Source 'preservation' 'Verse.Pawn_CarryTracker' 53 81))},
 [ordered]@{id='OUT06';finding='Best calls TryFindBestBetterStoreCellFor from Unstored, scanning registered slot groups in priority order. It requires priority above current and not below a found priority, matching faction for Thing parents, and HaulDestinationEnabled. Production uses the cell/slot-group search, not the broader non-slot container search.';sources=@((Source 'food' 'Verse.AI.Toils_Recipe' 249 256),(Source 'work' 'RimWorld.StoreUtility' 144 205))},
 [ordered]@{id='OUT07';finding='Specific calls TryFindBestBetterStoreCellForIn on its ISlotGroup directly, without Best outer priority/faction/enabled loop. Shared worker rejects null or actual-Thing filter mismatch, then searches CellsList. Distance is horizontal squared distance and the loop can stop after a small randomized fraction; not guaranteed global nearest or minimum path cost.';sources=@((Source 'work' 'RimWorld.StoreUtility' 207 240))},
 [ordered]@{id='OUT08';finding='Good store cells check physical capacity/stack blockers, cell forbidding, destination reservations, static fire, construction blocking and carrier reachability. An enabled UI destination is not proof of a free reachable cell for this actual product.';sources=@((Source 'work' 'RimWorld.StoreUtility' 103 142),(Source 'work' 'RimWorld.StoreUtility' 327 377))},
 [ordered]@{id='OUT09';finding='When initial Best/Specific search finds no cell, the first product is attempted Near the maker and production ends Succeeded. Specific has no initial automatic fallback to Best. A full/filter-blocked/unreachable but valid group does not itself invalidate the stored policy.';sources=@((Source 'food' 'Verse.AI.Toils_Recipe' 249 294),(Source 'stonecutting' 'RimWorld.Bill_Production' 346 445))},
 [ordered]@{id='OUT10';finding='HaulToCellStorageJob targets the actual product and destination cell, sets ToCellStorage and opportunistic duplicates, and derives job.count from storage capacity. job.count is not necessarily the actual carried stackCount. The direct new haul job has no bill assignment; changing/deleting that bill is not a bill-link cancellation of this independent shipment.';sources=@((Source 'work' 'Verse.AI.HaulAIUtility' 141 179),(Source 'food' 'Verse.AI.Toils_Recipe' 278 284),(Source 'work' 'Verse.AI.JobDriver_HaulToCell' 1 156))},
 [ordered]@{id='OUT11';finding='HaulToCell skips pickup when already carrying targetA, reserves its targets, and checks destination storage validity while carrying. Group removal, changed filter or capacity can fail an en-route job. Generic cleanup clears reservations and conditionally drops carried contents Near unless job policy/override retains them; this is distinct from initial output selection.';sources=@((Source 'work' 'Verse.AI.JobDriver_HaulToCell' 16 142),(Source 'work' 'Verse.AI.Toils_Haul' 254 294),(Source 'work' 'Verse.AI.Pawn_JobTracker' 475 521))},
 [ordered]@{id='OUT12';finding='At-place Direct drop failure or partial placement can try another Best storage cell, then haul-aside; the default tryStoreSame=false does not constrain remainder to the original Specific group. In the extreme no-place branch the original destroys the carried item and logs a warning. Web cargo-preservation/drop-near failure handling is an adaptation, not an exact copy of this fallback tree.';sources=@((Source 'work' 'Verse.AI.Toils_Haul' 320 385))},
 [ordered]@{id='OUT13';finding='ValidateSettings validates storeGroup and includeGroup independently. Invalid output reference becomes null and Specific becomes DropOnFloor. Zone registration, single-building haul-group registration, and StorageGroup manager membership have different validity checks. Validation does not clear a reference solely for filter incompatibility or no free cells.';sources=@((Source 'stonecutting' 'RimWorld.Bill_Production' 346 445))},
 [ordered]@{id='OUT14';finding='The output menu enumerates registered slot groups; linked StorageGroups are deduplicated and ungrouped Building_Storage must implement IRenameable to appear through that branch. CanPossiblyStore checks first product Def for countable recipes, or returns true for noncountable recipes. Incompatible menu options have null actions; an already-selected incompatible group gets an incompatible label rather than deletion-style validation.';sources=@((Source 'production-bills' 'RimWorld.Dialog_BillConfig' 216 244),(Source 'production-bills' 'RimWorld.Dialog_BillConfig' 423 470),(Source 'production-bills' 'RimWorld.Dialog_BillConfig' 586 603),(Source 'stonecutting' 'Verse.RecipeWorkerCounter' 10 17),(Source 'stonecutting' 'Verse.RecipeWorkerCounter' 156 163))},
 [ordered]@{id='OUT15';finding='storeMode, storeGroup and includeGroup are saved independently; slot references serialize the ILoadReferenceable group or slot parent and resolve back to ISlotGroup. Missing storeMode defaults to BestStockpile. Clone copies both group references and the mode; it does not duplicate physical storage.';sources=@((Source 'stonecutting' 'RimWorld.Bill_Production' 113 175),(Source 'stonecutting' 'RimWorld.Bill_Production' 448 466))},
 [ordered]@{id='OUT16';finding='Pawn_JobTracker saves current job, driver and queue deeply and reconnects driver pawn/job after loading. Pawn_CarryTracker independently saves its one-stack innerContainer deeply. Output mode persistence alone does not prove an active shipment roundtrip; actual job/driver/product identity must also be compared.';sources=@((Source 'work' 'Verse.AI.Pawn_JobTracker' 90 110),(Source 'preservation' 'Verse.Pawn_CarryTracker' 10 40))},
 [ordered]@{id='OUT17';finding='Composition of matched static paths: uninstall minifies by despawning; Thing.DeSpawn removes the haul destination and manager removes its SlotGroup. Bill validation therefore invalidates a single uninstalled shelf target. Building_Storage.DeSpawn does not remove linked-group membership (Destroy does). Its AllSlotCells is empty while unspawned. A still-registered linked group containing only packed shelves passes group validation but has no physical cells; initial product search fails/drop-near without resetting Specific solely for zero cells. Destruction/member removal can separately dissolve the group.';sources=@((Source 'furniture-reinstall' 'RimWorld.MinifyUtility' 8 28),(Source 'food' 'Verse.Thing' 930 947),(Source 'food' 'Verse.Thing' 1003 1018),(Source 'logistics' 'RimWorld.HaulDestinationManager' 87 117),(Source 'logistics' 'RimWorld.Building_Storage' 83 98),(Source 'logistics' 'RimWorld.Building_Storage' 152 187),(Source 'shelf-storage' 'RimWorld.SlotGroup' 60 63),(Source 'shelf-storage' 'RimWorld.StorageGroup' 71 86),(Source 'storage-groups' 'Verse.StorageGroupManager' 28 38),(Source 'storage-groups' 'Verse.StorageGroupManager' 53 66),(Source 'stonecutting' 'RimWorld.Bill_Production' 414 445))},
 [ordered]@{id='OUT18';finding='Counting is a separate policy: RecipeWorkerCounter uses includeGroup, with all-map/resource/held/carried branches when appropriate, and group HeldThings for an include-group branch. Output destination does not implicitly become the count scope. List-based CountValidThings and carried counting have different increments; no blanket stack-count formula is inferred from one branch.';sources=@((Source 'stonecutting' 'Verse.RecipeWorkerCounter' 20 122),(Source 'stonecutting' 'Verse.RecipeWorkerCounter' 165 181))}
)
$reaFile=Join-Path $base 'production-bills-rea-managed.json';$rea=Get-Content $reaFile -Raw|ConvertFrom-Json
if($rea.subject.digest.sha256 -ne $dllHash -or $rea.normalized_result.summary.module.mvid -ne '8e962ecc-7ac7-42d2-8f3b-1b16cd24d2cd'){throw 'REA identity mismatch'}
$e=[ordered]@{
 evidence_id='RW17-PRODUCTION-OUTPUT';version_text=(Get-Content (Join-Path $GameRoot 'Version.txt') -Raw).Trim()
 source_sha256=$dllHash;engine_sha256=$engineHash;kind='Static derived reconstruction and bounded Core XML; no target execution or new decompilation'
 rea=[ordered]@{file='production-bills-rea-managed.json';sha256=Digest $reaFile;evidence_id=$rea.evidence_id;parent_evidence_id=$rea.normalized_result.parent_evidence_id;mvid=$rea.normalized_result.summary.module.mvid;metadata_coverage=$rea.normalized_result.summary.coverage.state}
 manifests=@(foreach($name in @($groups|Sort-Object)){[ordered]@{file="$name-manifest.json";sha256=Digest (Join-Path $base "$name-manifest.json")}})
 xml=[ordered]@{file=$xmlRelative;sha256=Digest $xmlFile;projection='Three literal Core BillStoreModeDef nodes; not complete loaded mod/DLC Def database';modes=$modes}
 claims=$claims
 limitations=@('Derived C# is not original source and unresolved dependencies are tolerated.','Initial selection failure, en-route failure and at-place fallback are distinct branches.','Specific skips the Best outer priority/faction/enabled checks; do not merge their conditions.','Packed linked-group conclusion is composed static evidence, not a native packed-shelf trial.','Native runtime is recorded separately and covers one club under Best and Drop, plus Specific settings/deletion only.','REA framework metadata does not prove the game runtime.')
}
$text=(LF ($e|ConvertTo-Json -Depth 40))+[char]10;$output=Join-Path $base 'production-output-evidence.json'
if($Check){if([IO.File]::ReadAllText($output) -cne $text){throw 'Retained production-output evidence differs'};"Production-output replay verified: $($claims.Count) claims, $($modes.Count) modes"}
else{[IO.File]::WriteAllText($output,$text,[Text.UTF8Encoding]::new($false));"Collected $($claims.Count) production-output claims and $($modes.Count) modes"}
